// Agrega contas vencendo em UMA mensagem + SQL de flags
const THIAGO_NUMERO = '5511910441709';
const contas = items.filter(i => i.json && i.json.id && i.json.janela);
if (!contas.length) return [];

function money(v){ if (v == null) return ''; const n = Number(v); return isNaN(n) ? '' : ' R$ ' + n.toFixed(2).replace('.', ','); }

const atrasadas = contas.filter(c => c.json.janela === 'atrasada');
const hoje = contas.filter(c => c.json.janela === 'hoje');
const amanha = contas.filter(c => c.json.janela === 'amanha');
const prox = contas.filter(c => c.json.janela === 'proximos_3d');

let partes = [];
if (atrasadas.length) partes.push('*ATRASADAS:*\n' + atrasadas.map(c => `  #${c.json.id} ${c.json.descricao}${money(c.json.valor)} (venceu ${c.json.venc})`).join('\n'));
if (hoje.length) partes.push('*Vencem HOJE:*\n' + hoje.map(c => `  #${c.json.id} ${c.json.descricao}${money(c.json.valor)}`).join('\n'));
if (amanha.length) partes.push('*Vencem amanha:*\n' + amanha.map(c => `  #${c.json.id} ${c.json.descricao}${money(c.json.valor)}`).join('\n'));
if (prox.length) partes.push('*Proximos 3 dias:*\n' + prox.map(c => `  #${c.json.id} ${c.json.descricao}${money(c.json.valor)} (${c.json.venc})`).join('\n'));

if (!partes.length) return [];

const total = contas.reduce((s,c) => s + Number(c.json.valor || 0), 0);
let texto = 'Contas a pagar:\n\n' + partes.join('\n\n');
if (total > 0) texto += `\n\nTotal: R$ ${total.toFixed(2).replace('.', ',')}`;
texto += '\n\nQuando pagar, manda o comprovante ou fala "paguei a #ID" que eu dou baixa e lanco na planilha.';

// Flags: marca lembrete enviado conforme janela
const sqls = [];
const idsHoje = hoje.map(c => c.json.id);
const idsAmanha = amanha.map(c => c.json.id);
const idsProx = prox.map(c => c.json.id);
if (idsHoje.length) sqls.push(`UPDATE giulia_contas_pagar SET lembrete_dia_enviado = TRUE WHERE id IN (${idsHoje.join(',')});`);
if (idsAmanha.length) sqls.push(`UPDATE giulia_contas_pagar SET lembrete_1d_enviado = TRUE WHERE id IN (${idsAmanha.join(',')});`);
if (idsProx.length) sqls.push(`UPDATE giulia_contas_pagar SET lembrete_3d_enviado = TRUE WHERE id IN (${idsProx.join(',')});`);

return [{ json: { send_to: THIAGO_NUMERO, send_text: texto, sql_flags: sqls.join('\n') || 'SELECT 1;' } }];
